






















"""Self-test suite for Crypto.Hash.SHA"""

from binascii import hexlify

from Crypto.Hash import SHA1
from Crypto.SelfTest.Hash.common import make_hash_tests
from Crypto.SelfTest.loader import load_test_vectors



test_data_various = [

    ("a9993e364706816aba3e25717850c26c9cd0d89d", "abc"),

    ("84983e441c3bd26ebaae4aa1f95129e5e54670f1", "abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq"),





    ("dea356a2cddd90c7a7ecedc5ebb563934f460452", "01234567" * 80, '"01234567" * 80'),
]


def _load_test_data():
    test_vectors = (
        load_test_vectors(("Hash", "SHA1"), "SHA1ShortMsg.rsp", "KAT SHA-1", {"len": lambda x: int(x)}) or []
    )

    test_data = test_data_various[:]
    for tv in test_vectors:
        try:
            if tv.startswith("["):
                continue
        except AttributeError:
            pass
        if tv.len == 0:
            tv.msg = b""
        test_data.append((hexlify(tv.md), tv.msg, tv.desc))
    return test_data


TestVectors = make_hash_tests(SHA1, "SHA1", _load_test_data(), digest_size=20, oid="1.3.14.3.2.26")
